import{_ as o,o as r,c as e,a5 as n}from"./chunks/framework.R-FQ1xZ2.js";const h=JSON.parse('{"title":"⑱ 面试深挖与口径","description":"","frontmatter":{"title":"⑱ 面试深挖与口径","order":17},"headers":[],"relativePath":"projects/yyhelp/17-interview.md","filePath":"projects/yyhelp/17-interview.md","lastUpdated":null}'),s={name:"projects/yyhelp/17-interview.md"};function d(g,t,a,l,c,p){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="_18-面试深挖与口径" tabindex="-1">⑱ 面试深挖与口径 <a class="header-anchor" href="#_18-面试深挖与口径" aria-label="Permalink to &quot;⑱ 面试深挖与口径&quot;">​</a></h1><blockquote><p><strong>一句话</strong>：这一页不是知识，是<strong>你把前十七页变现的地方</strong>——三档陈述、五条追问链、一张口径表、三条红线。</p></blockquote><h2 id="这一页要回答什么" tabindex="-1">这一页要回答什么 <a class="header-anchor" href="#这一页要回答什么" aria-label="Permalink to &quot;这一页要回答什么&quot;">​</a></h2><p>前面十七页解决「我懂这个项目」。这一页解决「我怎么在十分钟里让面试官相信我真的懂」。</p><p>读完这一页你应该能：</p><ul><li>用 30 秒 / 2 分钟 / 5 分钟三档讲这个项目，都不超时、都不注水；</li><li>面对「多智能体到底有没有用」「40 道题是不是太少」这类问题，<strong>主动把实验设计的边界讲出来</strong>，而不是防守；</li><li>报任何一个数字时，条件反射地带上分母、口径和日期；</li><li>知道哪三个说法<strong>绝对不能出口</strong>。</li></ul><div class="tip custom-block"><p class="custom-block-title">与通用预演的分工</p><p><a href="/learn/interview/project-grilling.html">项目深挖预演</a> 是<strong>两个项目通用</strong>的打法（开场三问怎么答、被问住了怎么办）。 这一页是 <strong>YYHelp 专属</strong>的口径：只有这个项目才有的数字、缺陷和追问链。</p></div><h2 id="一、三档陈述-照着背" tabindex="-1">一、三档陈述（照着背） <a class="header-anchor" href="#一、三档陈述-照着背" aria-label="Permalink to &quot;一、三档陈述（照着背）&quot;">​</a></h2><h3 id="_30-秒版-电梯陈述" tabindex="-1">30 秒版（电梯陈述） <a class="header-anchor" href="#_30-秒版-电梯陈述" aria-label="Permalink to &quot;30 秒版（电梯陈述）&quot;">​</a></h3><blockquote><p>我做了个电商客服场景的多轮对话 Agent，用 LangGraph 搭主图：九类意图分流到五个出口，各自汇合到主力 Agent 的 ReAct 循环。检索是 Milvus 单库双路，dense 加 BM25，RRF 融合后精排。</p><p>和一般 demo 不一样的地方有三个：<strong>写操作带幂等键和人工确认</strong>；<strong>可观测是自研 JSONL 打底、Langfuse 增强的双后端，写入失败会显式降级而不是把主流程搞挂</strong>；<strong>评测做成了回归门禁，跑出来是三态退出码，能直接进 CI</strong>。</p><p>我还做了架构对比实验：让多智能体和单智能体<strong>共享同一套骨架</strong>，只把&quot;谁决定下一个专家&quot;这一个变量分开，跑 <strong>120 题 × 2 臂</strong>的配对盲测（含 Holm 校正与功效分析）。结论是<strong>多智能体完成率显著低 14.2 个百分点、延迟高 43%，只在 token 上省 12.5%</strong>——所以主链路保持单智能体。完整链条见 <a href="/learn/interview/architecture-ab.html">架构对比实验</a>。</p></blockquote><h3 id="_2-分钟版-加进「为什么这么做」" tabindex="-1">2 分钟版（加进「为什么这么做」） <a class="header-anchor" href="#_2-分钟版-加进「为什么这么做」" aria-label="Permalink to &quot;2 分钟版（加进「为什么这么做」）&quot;">​</a></h3><p>在 30 秒版基础上补三件事：</p><ol><li><strong>为什么用状态图而不是手写循环</strong>：前作（科研文献 RAG）是直线流程——问题进来、检索、生成、校验、出答案。这个项目要处理退款、查单、建工单，路径会分叉、会回到上游、会中途停下来问用户。<strong>手写这种控制流只有两个结局：要么写成一坨 if-else，要么把状态散落在闭包里没法持久化。</strong> 状态图把「状态形状」和「走哪条边」分开，前者是 schema，后者是纯函数，两个都能单独测。</li><li><strong>为什么检索要单库双路</strong>：中文查询里术语和口语混在一起，纯向量对「退货运费谁出」这种口语问法召不回条款原文，纯稀疏对「七日无理由」这种同义改写又召不回。两路各取 top-20 用 RRF 融，再把融合结果交给精排。<strong>RRF 的 k 取 60、两路等权，是因为它只用名次不用分数</strong>——BM25 的原始分是负的（实测 −0.66 那一档），和余弦相似度根本不在一个量纲上，硬加权就得先做归一化，那又多一个要调的参数。</li><li><strong>为什么评测要统计检验而不是看均值</strong>：四十题两臂，完成率 40/40 对 39/40，差 2.5 个百分点看着像有提升。但配对检验给的 p 值是 <strong>0.323</strong>、Wilcoxon 是 <strong>1.0</strong>，因为<strong>两臂在同一道题上几乎同对同错（39/40 一致）</strong>，有效样本量其实只有 1。均值的差完全被噪声吃掉了。后来我把题集扩到 <strong>120 题（40 题 × 3 个问法变体）</strong>，差异才显出统计显著——<strong>n=40 时置信区间是 ±14pp，真实差异刚好在可检出边界外</strong>。</li></ol><h3 id="_5-分钟版-主线是三次「我改了主意」" tabindex="-1">5 分钟版（主线是三次「我改了主意」） <a class="header-anchor" href="#_5-分钟版-主线是三次「我改了主意」" aria-label="Permalink to &quot;5 分钟版（主线是三次「我改了主意」）&quot;">​</a></h3><p>面试官听 5 分钟陈述时，真正在听的是<strong>你有没有独立判断</strong>。所以主线讲三次推翻自己的过程：</p><p><strong>第一次</strong>：「我本来打算让不同专家挂不同工具，目的是省上下文。做完发现更关键的价值不在这里——<strong>收窄可见性真正防的是越权写操作</strong>。我最后只给 MCP 暴露了两个只读工具（<code>search_kb</code>、<code>query_order</code>），把 <code>create_ticket</code>、<code>query_refund_policy</code>、<code>query_logistics</code> 三个显式挡在外面。」</p><p><strong>第二次</strong>：「我本来以为多智能体一定更好——专家分工、各管一摊，听起来就比一个 Agent 全包强。第一轮四十题跑出来是『完成率不显著、墙钟显著更差』，我写的是『不证』而不是『证否』，因为功效分析说 +5pp 要 76 题才测得出。<strong>但后来我发现这个结论本身也不可信</strong>：做人工锚定抽样时查出三层问题——检索后端从来没接上（跑的是关键词替身）、向量路因环境变量指向空目录而静默降级、裁判把『礼貌拒答』判成完成任务。修完之后完成率从 97.5% 掉到 60-75%，<strong>这才是真实水平</strong>。再扩样到 120 题，结论升级为统计显著：多智能体完成率低 14.2 个百分点（p=0.0005）、延迟高 43%，只省 12.5% 的 token。<strong>这一轮教会我：数字变好看时先怀疑链路，别先怀疑模型。</strong>」</p><p><strong>第三次</strong>：「并行实验我一开始得出的是『没有收益』。后来发现是我自己的锅：<strong>那个 CPU 密集的块写在函数体里每次重新构造，构造过程本身持有 GIL，把并行收益全掩盖了</strong>。挪到模块级预建之后，加速比从 1.02 倍变成 6.41 倍（并发度 8）。这个坑比结论本身值钱——它教会我<strong>测并发性能之前先确认被测对象真的释放了 GIL</strong>。」</p><h2 id="二、五条追问链-现场问答" tabindex="-1">二、五条追问链（现场问答） <a class="header-anchor" href="#二、五条追问链-现场问答" aria-label="Permalink to &quot;二、五条追问链（现场问答）&quot;">​</a></h2><h3 id="追问链-1-多智能体到底有没有用" tabindex="-1">追问链 1：多智能体到底有没有用 <a class="header-anchor" href="#追问链-1-多智能体到底有没有用" aria-label="Permalink to &quot;追问链 1：多智能体到底有没有用&quot;">​</a></h3><blockquote><p><strong>面试官</strong>：你提到多智能体没有收益，那为什么还要做？</p><p>「做之前我不知道结论。做完之后的判断是：<strong>在这批任务、这个实现质量下，多智能体没有完成率收益，还带来确定性的成本。</strong> 最新一轮是 <strong>120 题 × 2 臂</strong>：完成率 <strong>63.3% 对 77.5%（−14.2pp，p=0.00053）</strong>、墙钟 <strong>24.7 秒对 17.3 秒（慢 1.43 倍，p≈0）</strong>，两个指标 Holm 校正后都是 REGRESSION；只有 token 是省 12.5% 的 IMPROVEMENT。<strong>用 12.5% 的 token 换 14.2pp 完成率和 43% 延迟，对在线客服是亏的。</strong>」</p><blockquote><p><strong>面试官</strong>：这个结论你是怎么得到的？（<strong>注意：这一问会引出整条故事线</strong>）</p><p>「四轮实验。第一轮我拿到的是『完成率 100% 对 97.5%，不显著』——<strong>那个数字是假的</strong>。我做了人工锚定抽样（逐条核对答案与标准答案），查出三层根因：① 检索后端从来没接上，整场跑的是关键词替身；② 向量路因为一个环境变量指向空目录而静默降级，只剩 BM25；③ 裁判 rubric 写着『诚实拒答也算完成』，把检索失败判成了满分。</p><p>修完之后完成率掉到 60-75%——<strong>这才是真实水平</strong>。第二轮结论是『打平』（70% 对 70%），我又把题集扩到 120 题，差异才达到统计显著。完整链条我单独写了一页。」</p><blockquote><p><strong>面试官</strong>：40 道题说打平、120 道题说显著，哪个可信？</p><p>「120 题更可信，而且<strong>不是挑样本挑出来的，是功效算出来的</strong>。n=40 时置信区间是 [−14pp, +14pp]，真实的 −14.2pp 刚好在可检出边界外；n=120 把边界压到 ±11pp。ψ=0.208 时，测 +5pp 需要 652 题、+10pp 需要 161 题——<strong>小幅差异我到现在也判不了，这一点必须说清。</strong>」</p><blockquote><p><strong>面试官</strong>：n_eff = 1 是什么意思？</p><p>「是我自己算的一个诊断量。第一轮 40 题里两臂在 39 道题上对错完全一致，只有 1 道题有差异。配对检验的方差来自<strong>配对差异</strong>，当绝大部分配对差异为零时，有效样本量接近 1。<strong>这也是为什么均值差 2.5pp 却不能下结论</strong>——不是样本小，是<strong>有效信息量小</strong>。扩样到 120 题后不一致对升到 20.8%，信号才够。」</p><blockquote><p><strong>面试官</strong>：那你觉得什么时候该用多智能体？</p><p>「三条同时成立才考虑：<strong>子任务之间真的能并行或接力</strong>、<strong>每个子任务需要不同的工具集或提示词</strong>、<strong>分派对问法变化足够鲁棒</strong>。三条缺一条，单 Agent 加一个好的路由就够了。第三条是我这轮新加的——因为我发现 <strong>multi 的脆弱点不在模型能力，在分派鲁棒性</strong>。」</p><blockquote><p><strong>面试官</strong>：分派鲁棒性是什么意思？</p><p>「同一批题、只换问法：<strong>multi 完成率掉 6.7 个百分点（70%→63.3%），single 反而升 7.5 个百分点（70%→77.5%）。</strong> 原因是 multi 的收益依赖『意图分类 → 计划 → 专家』这条链正确，而分派对口语变体不鲁棒——问法一变可能派错专家，而派错的专家工具集不匹配，答不出；single 用一个全工具专家，对问法天然更稳。<strong>所以改进方向不是多加专家，是让分派对问法不敏感</strong>（我后来加了规则兜底：疑问句式 + 规则关键词的题直接派给知识专家）。」</p></blockquote></blockquote></blockquote></blockquote></blockquote></blockquote><h3 id="追问链-2-写操作的副作用安全-含-mcp-高危题" tabindex="-1">追问链 2：写操作的副作用安全（含 MCP 高危题） <a class="header-anchor" href="#追问链-2-写操作的副作用安全-含-mcp-高危题" aria-label="Permalink to &quot;追问链 2：写操作的副作用安全（含 MCP 高危题）&quot;">​</a></h3><blockquote><p><strong>面试官</strong>：查订单、建工单这类写操作，你怎么保证不出事？</p><p>「三层。<strong>第一层是幂等键</strong>：每个写操作带一个由会话 ID 加意图加参数算出来的键，重复提交直接返回上次结果，不会建两张工单。<strong>第二层是人工确认</strong>：所有会改变外部状态的调用都要先拿到用户明确同意，Agent 不能自己决定替用户下单。<strong>第三层是工具可见性收窄</strong>：不该看到某个工具的专家，在提示词层面根本看不到它的 schema。」</p><blockquote><p><strong>面试官</strong>：那为什么 MCP 只暴露两个工具？</p><p>「因为 MCP 是<strong>跨进程</strong>的边界，一旦暴露出去，控制权就不完全在我这边了。我暴露的两个都是只读的（<code>search_kb</code>、<code>query_order</code>），三个会改变状态的（<code>create_ticket</code>、<code>query_refund_policy</code>、<code>query_logistics</code>）全部挡在外面。<strong>在同一个进程里我可以用代码保证幂等和确认，跨了进程我只能靠契约保证，那就不该把写操作放出去。</strong>」</p><blockquote><p><strong>面试官</strong>：MCP 和原生 tool 你怎么选？</p><p>「我的判断是<strong>看这个工具属于谁</strong>。工具的实现和 Agent 在同一个仓库、同一个部署单元，用原生 tool 更好——延迟低、能直接拿到异常和类型。工具的实现属于另一个团队、另一套生命周期（比如公司内部的工单系统、别人写的浏览器工具），那就用 MCP，把接口契约固定下来，各自独立升级。<strong>我做了 ADR 记录这个取舍</strong>，结论是混合：核心工具走原生，外部能力走 MCP。」</p><blockquote><p><strong>面试官</strong>：接 MCP 遇到什么坑？</p><p>「一个很具体的：<strong>一次 streamable-http 往返还附带 17 行 stderr 噪声</strong>，把日志冲得没法看。我最后集中治理了 12 个 logger 的级别，静音到 <code>WARNING</code>——注意不是 <code>CRITICAL</code>，因为 <code>WARNING</code> 以上还是需要看到的。另外还有一类假故障：httpx 默认读环境变量里的代理设置，本机配了代理时会去连 <code>[::1]</code> 然后超时，看起来像 MCP 服务挂了，其实是代理配置问题。」</p></blockquote></blockquote></blockquote></blockquote><h3 id="追问链-3-中文检索的静默故障" tabindex="-1">追问链 3：中文检索的静默故障 <a class="header-anchor" href="#追问链-3-中文检索的静默故障" aria-label="Permalink to &quot;追问链 3：中文检索的静默故障&quot;">​</a></h3><blockquote><p><strong>面试官</strong>：检索这块你遇到最难查的问题是什么？</p><p>「一个<strong>不报错、只是返回空</strong>的故障。Milvus 建集合的时候如果没指定分词器，它会用默认 analyzer；对中文来说，默认分词器切出来的稀疏向量基本没有区分度，BM25 那一路<strong>静默返回空结果</strong>——不抛异常、不写错误日志，只是召回为空。我一开始的排查方向全错了，因为没有任何错误可看。」</p><blockquote><p><strong>面试官</strong>：怎么定位的？</p><p>「反推。先确认向量那一路正常，那问题只在稀疏路。再单独打稀疏查询，发现返回 0 条。然后拿同一批文档在 <code>rank_bm25</code> 上跑对照，能召回——说明数据没问题，是 Milvus 侧的配置。最后查 Milvus 的 analyzer 参数，加 <code>analyzer_params={&quot;tokenizer&quot;:&quot;jieba&quot;}</code> 就恢复了。<strong>教训是：配置类开关必须配一个『能失败的断言』。只验证『没报错』等于没验证。</strong>」</p><blockquote><p><strong>面试官</strong>：这类静默失败你怎么系统性防住？</p><p>「我把这条总结成一条纪律写进了项目复盘：<strong>任何配置项，如果配错了的表现是『静默退化』而不是『报错』，就必须有一个探针去主动验证它生效了。</strong> 具体到这个项目：稀疏路在启动自检里打一次查询，命中数为零就报错退出。同样的纪律我还用在 Langfuse 接入上——v4 和 v2 的 API 不兼容，<code>trace</code>、<code>span</code>、<code>generation</code> 三个成员实测都不存在，如果我不做一次真实的写入探针，就会得到『接好了但其实什么都没记』。」</p><blockquote><p><strong>面试官</strong>：还有别的静默问题吗？</p><p>「有，而且更隐蔽：<strong>v1 有 11 个 selftest 从来没被 pytest 执行过。</strong> 自检函数写在文件里、能被 import，但没有任何入口把它们收集进测试集。结果是 <code>state.py</code> 的一个缺陷红了不知道多久——<strong>没人看，因为根本没人跑。</strong> 我后来做了一个总闸把它们全部登记进来，v1 十四条加 v2 十六条一共三十条自检入口。这件事让我对『写下 ≠ 执行』这句话有实感。」</p></blockquote></blockquote></blockquote></blockquote><h3 id="追问链-4-条件边装配错误" tabindex="-1">追问链 4：条件边装配错误 <a class="header-anchor" href="#追问链-4-条件边装配错误" aria-label="Permalink to &quot;追问链 4：条件边装配错误&quot;">​</a></h3><blockquote><p><strong>面试官</strong>：LangGraph 用下来踩过什么坑？</p><p>「一个能 import、能编译、语法全对、<strong>一跑就崩</strong>的坑。<code>add_conditional_edges(source, path_fn, path_map)</code> 的第三个参数是<strong>从 <code>path_fn</code> 的返回值映射到目标节点名</strong>。我第一版让路由函数直接返回节点名，却把另一张表当 map 传了进去，运行时报 <code>KeyError: &#39;agent_memory&#39;</code>，形态是 <code>During task with name &#39;triage&#39; and id &#39;a06e0b0c-...&#39;</code>。」</p><blockquote><p><strong>面试官</strong>：为什么单测没抓住？</p><p>「因为路由函数本身是纯函数，单测它是对的。<strong>错的是装配</strong>——图在构造的时候不校验这张映射表，只有真正跑起来、走第一条边的时候才暴露。所以我的结论是：<strong>装配类错误必须靠运行图来验，不能靠读代码或测纯函数。</strong> 后来我加了一个冒烟测试，只做一件事：把图跑通一条最短路径。」</p><blockquote><p><strong>面试官</strong>：state 的 schema 你怎么设计？</p><p>「分两类。<strong>普通字段是覆盖语义</strong>，比如 <code>query</code>、<code>intent</code>。<strong>累积字段需要 reducer</strong>，比如消息列表要用追加而不是覆盖，否则每一轮都会把历史冲掉。另外有一条纪律：<strong>汇合点的 state 形状必须一致</strong>——不同分支往同一个节点汇的时候，如果一边写了 <code>documents</code> 一边没写，下游读它就会拿到 <code>None</code>。我最后是用 TypedDict 定形状、在自检里断言字段齐全。」</p><blockquote><p><strong>面试官</strong>：为什么用 TypedDict 不用 Pydantic？</p><p>「因为 LangGraph 的 state 在每个节点之间传递，如果每次进出都做一次完整校验，开销会叠在每一跳上。<strong>我的取舍是：state 的形状用 TypedDict 做静态约束、靠自检兜底；而工具入参用 Pydantic，因为那是外部输入，必须运行时严格校验。</strong> 一个要便宜，一个要严格，用途不同。」</p><blockquote><p><strong>面试官</strong>：那工具校验失败怎么办？</p><p>「<strong>不炸图。</strong> 校验失败时把错误信息作为工具结果写回 state，让模型自己看到『你参数传错了，字段 X 缺失』然后重试。这和『直接抛异常终止整个请求』是完全不同的用户体验——前者模型有一次自我修正的机会，后者用户直接看到一个 500。」</p></blockquote></blockquote></blockquote></blockquote></blockquote><h3 id="追问链-5-可观测为什么自研" tabindex="-1">追问链 5：可观测为什么自研 <a class="header-anchor" href="#追问链-5-可观测为什么自研" aria-label="Permalink to &quot;追问链 5：可观测为什么自研&quot;">​</a></h3><blockquote><p><strong>面试官</strong>：为什么不用现成的可观测平台，要自己写 JSONL？</p><p>「我用了，但<strong>不是当默认路径</strong>。默认路径是自研 JSONL：零第三方依赖、离线可审计、格式我自己定。Langfuse v4 是增强路径，接上去之后能看到可视化的链路。两条路径用同一个 <code>trace_id</code> 缝合，可以互相跳转。」</p><blockquote><p><strong>面试官</strong>：为什么把自研放在默认？</p><p>「因为<strong>可观测组件不能反过来把主流程搞挂</strong>。第三方 SDK 会升级、会改 API、会有网络问题。我的设计是：写 trace 失败<strong>绝不抛异常</strong>，而是降级写一条 <code>observability_degraded</code> 事件，主流程照常返回答案。这样最坏情况是我丢了这段链路，而不是用户拿不到答案。」</p><blockquote><p><strong>面试官</strong>：Langfuse 接入具体有什么问题？</p><p>「v4 和 v2 的 API 完全不兼容。我按文档写的 <code>trace</code>、<code>span</code>、<code>generation</code> 三个成员，<strong>实测下来一个都不存在</strong>。这件事让我对『文档写的』和『实际能跑』之间的距离有了具体认识——所以我说配置类的东西必须配能失败的断言。」</p><blockquote><p><strong>面试官</strong>：那你 trace 里都记什么？</p><p>「按『回答三个问题』来设计：<strong>出错了没有</strong>（每个节点进出加错误标记）、<strong>慢在哪一跳</strong>（每跳的耗时）、<strong>花了多少 token</strong>（每次 LLM 调用的输入输出 token）。三个问题之外的东西我一开始没记，因为记多了没人看。后来加了一个飞轮需要的东西：<strong>检索快照</strong>——把这次召回到了什么、真正喂给模型的是什么，两份都存下来。」</p></blockquote></blockquote></blockquote></blockquote><h2 id="三、口径表-这个项目能报的数-报之前先看分母" tabindex="-1">三、口径表：这个项目能报的数（报之前先看分母） <a class="header-anchor" href="#三、口径表-这个项目能报的数-报之前先看分母" aria-label="Permalink to &quot;三、口径表：这个项目能报的数（报之前先看分母）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数字</th><th>值</th><th><strong>必须同时说的口径</strong></th></tr></thead><tbody><tr><td>代码规模</td><td>28 个文件 ≈ 9,957 行</td><td>不含 <code>.venv</code> 与 <code>__pycache__</code>；最大单文件 <code>graph/supervisor.py</code> 1,827 行</td></tr><tr><td>意图分流</td><td>9 类意图 → 5 个出口</td><td>出口名 <code>kb_faq</code> / <code>order_ops</code> / <code>refund_flow</code> / <code>service_ops</code> / <code>agent_free</code>；<strong>规则咨询类疑问句有兜底改派</strong>（见分派鲁棒性）</td></tr><tr><td>专家与工具</td><td>5 个专家 × 5 个工具，每专家可见 1–3 个</td><td>可见性探针 9 条</td></tr><tr><td><strong>多智能体完成率</strong></td><td><strong>63.3% vs 77.5%</strong></td><td><strong>120 题 × 2 臂 = 240 条</strong>（40 题 × 3 问法变体）；<strong>−14.2pp</strong>，t p=0.00053、Wilcoxon p=0.0032，<strong>Holm 校正后仍显著 → REGRESSION</strong></td></tr><tr><td>多智能体 tokens</td><td>4,708 vs 5,379 / 问</td><td>同上 120 题；<strong>multi 省 12.5%</strong>，p=0.00034 → IMPROVEMENT</td></tr><tr><td>多智能体墙钟</td><td>24.7s vs 17.3s</td><td>同上 120 题；<strong>1.43 倍</strong>，t p≈0 → REGRESSION</td></tr><tr><td>分派鲁棒性</td><td>原题 70% → 变体 63.3%（multi）；70% → 77.5%（single）</td><td>同一批题只换问法；<strong>multi 掉 6.7pp，single 升 7.5pp</strong></td></tr><tr><td>有效样本量</td><td>ψ = 0.208（不一致对占比）</td><td>第一轮 40 题时 ψ=0.025（39/40 同对同错），信号被噪声吃掉</td></tr><tr><td>功效分析</td><td>+5pp 需 652 题 / +10pp 需 161 题 / +20pp 需 39 题</td><td>ψ=0.208、α=0.05、power=0.8；<strong>n=40 时 CI 为 ±14pp，真实差异刚好在边界外</strong></td></tr><tr><td>评测集</td><td><strong>120 题</strong>（40 题 × 3 变体）</td><td>原集：single_hop 12 / synonym 8 / unanswerable 8 / multi_hop 6 / exact_term 6；变体为 LLM 改写问法、<strong>gt 复用原题</strong></td></tr><tr><td>裁判校准</td><td>5 条锚定题 + 参考事实注入</td><td>锚定不全对 → <strong>整批标签作废（退出码 2）</strong>；参考事实为 gt chunk 文本</td></tr><tr><td>前置闸门</td><td>3 道（维度 / 检索后端 / 端到端 smoke）</td><td>跑题前检查；<strong>配置漂移静默降级是真实踩过的坑</strong></td></tr><tr><td>知识库</td><td>163 chunk / 9 doc</td><td><strong>合成语料</strong>（教学用途，非真实商家条款），无真实用户</td></tr><tr><td>检索融合</td><td>RRF k = 60</td><td>BM25 原始分为<strong>负值</strong>；融合分区间约 0.03 量级，<strong>不能和余弦相似度混比</strong></td></tr><tr><td>检索性能</td><td>encode 稳态 <strong>0.03 s/条</strong></td><td>首次 12 s 是<strong>模型加载</strong>（一次性）；不是瓶颈，<strong>瓶颈在 LLM 调用链</strong></td></tr><tr><td>长期记忆门槛</td><td>0.60 / 0.75 / 0.80 / 0.85</td><td>依次 preference / fact / solution / correction</td></tr><tr><td>记忆半衰期</td><td>90 天 / 180 天 / 不衰减</td><td>preference / solution / fact 与 correction</td></tr><tr><td>MCP</td><td>只暴露 2 个只读工具</td><td>版本 <code>mcp&gt;=1.28,&lt;2</code>，实装 <strong>1.30.0</strong>；禁暴露 3 个写操作</td></tr><tr><td>并发实验</td><td>1.02× → 6.41×</td><td>并发度 8、3 次取中位数；<strong>1.02× 是错的那个</strong></td></tr><tr><td>压测（服务层）</td><td>6 并发 / 18 请求 → p50 74.8s、p95 120.7s</td><td>拒答路径 <strong>~1s 且零 token</strong>；<strong>瓶颈是 LLM 调用链</strong>（single 1.85 次/问、multi 3.95 次/问）</td></tr><tr><td>模型对比</td><td>flash vs v4-pro：p50 <strong>33.4s → 20.2s（−40%）</strong></td><td>同 10 题、single 臂、两次独立进程；token 相当</td></tr><tr><td>限流</td><td>60 次/分钟</td><td>鉴权在限流<strong>之前</strong></td></tr><tr><td>自检入口</td><td>37 条（v1 14 + v2 23）</td><td>v1 曾有 11 条从未被 pytest 执行</td></tr><tr><td>测试</td><td><code>pytest code/yyhelp_v2 -q</code> = <strong>37 passed</strong></td><td>v1 基线 126 passed</td></tr></tbody></table><h2 id="四、🚫-黑名单-这三个说法不要用" tabindex="-1">四、🚫 黑名单：这三个说法不要用 <a class="header-anchor" href="#四、🚫-黑名单-这三个说法不要用" aria-label="Permalink to &quot;四、🚫 黑名单：这三个说法不要用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>说法</th><th>为什么不能这么说</th><th>改说</th></tr></thead><tbody><tr><td>「多智能体效果更好」</td><td>完成率显著更低（−14.2pp）、延迟显著更差（1.43×），只有 token 占优</td><td>「<strong>在这批任务与这个实现质量下</strong>，多智能体完成率低 14.2 个百分点（p=0.0005）、延迟高 43%，只省 12.5% token；<strong>决定性变量是问题分布与延迟预算，不是行业名</strong>」</td></tr><tr><td>「检索准确率 90%+」/ 单独报一个 R@5</td><td>检索评测在这个项目里不是主评测对象，<strong>单独报一个不带口径的数会被追问到崩</strong></td><td>「检索指标我必须带 gt 版本和题量一起说；<strong>这个项目的评测重点是端到端任务完成率</strong>」</td></tr><tr><td>「上线了 / 有真实用户」</td><td><strong>没有真实用户，知识库是合成语料</strong></td><td>「是教学/自研项目，知识库为合成语料、评测集由我本人标注；<strong>它证明的是设计能力和工程纪律，不是线上规模</strong>」</td></tr><tr><td>「第一版就发现了问题」</td><td>第一版数字是假的（<strong>检索替身 + 裁判放水</strong>），是锚定抽样才揭穿的</td><td>「第一版我拿到的是漂亮的假数字，<strong>是人工锚定抽样把它查出来的</strong>——这一段我写在复盘第一段」</td></tr></tbody></table><h2 id="五、被问住时的四步法" tabindex="-1">五、被问住时的四步法 <a class="header-anchor" href="#五、被问住时的四步法" aria-label="Permalink to &quot;五、被问住时的四步法&quot;">​</a></h2><ol><li><strong>先确认问题边界</strong>：「您问的是设计意图还是实测结果？」——很多问题的答案在这两者里选一个就行。</li><li><strong>能答的部分直接答，不要因为一部分不会就整段垮掉</strong>：「这块我实测过，是 X。您问的那一半我没做，但我的判断会是 Y，依据是 Z。」</li><li><strong>明确区分「我不知道」和「我没做」</strong>。前者可以说「这个我不掌握」，后者要说清为什么没做——<strong>没做不扣分，编一个答案被拆穿才扣分。</strong></li><li><strong>把话题拉回你能控的地方</strong>：「这块我做得比较粗，不过我在同一个问题上踩过一个坑，值得说……」</li></ol><h2 id="六、自检清单" tabindex="-1">六、自检清单 <a class="header-anchor" href="#六、自检清单" aria-label="Permalink to &quot;六、自检清单&quot;">​</a></h2><ul><li>[ ] 30 秒版能一口气说完，不卡壳</li><li>[ ] 5 分钟版的「三次改了主意」能讲出完整因果，不只是结论</li><li>[ ] 五条追问链里每一条的<strong>第三层</strong>都能接住</li><li>[ ] 报「−14.2pp」时条件反射地带上「120 题、t p=0.00053、Holm 校正」</li><li>[ ] 报任何指标前先问自己：分母是什么</li><li>[ ] 别人说「多智能体效果更好」时，能不带情绪地用&quot;完成率 −14.2pp / 延迟 1.43× / token 省 12.5%&quot;回应</li><li>[ ] 能讲清&quot;第一版数字为什么是假的&quot;（三层根因）与&quot;怎么修的&quot;（闸门 + 锚定校准）</li><li>[ ] 三条黑名单一条都不会说出口</li><li>[ ] 被问住时用四步法，而不是硬编</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/learn/interview/project-grilling.html">项目深挖预演</a>——两个项目通用的打法</li><li><a href="/learn/interview/cheatsheet.html">🔥 面试随身数字卡</a>——两个项目所有可报数字的总表</li><li><a href="/learn/interview/agent.html">Agent 与工具调用高频题</a>——追问链背后的通用知识</li><li><a href="/learn/projects/yyhelp/11-evaluation.html">⑫ 评测与回归门禁</a>——2.11 倍和功效分析的完整出处</li><li><a href="/learn/projects/yyhelp/16-pitfalls.html">⑰ 工程踩坑实录</a>——本文提到的所有缺陷的完整版</li><li><a href="/learn/projects/rag/13-vs-yyhelp.html">⑭ 与 YYHelp 的对照</a>——被问「这两个项目什么关系」时的标准答案</li></ul>',39)])])}const u=o(s,[["render",d]]);export{h as __pageData,u as default};
